1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8" />
5	<meta name="viewport" content="width=device-width, initial-scale=1" />
6	<title>Bookmarks — prototype</title>
7	<style>
8	  :root { --bg:#f6f7f9; --card:#fff; --ink:#1c2430; --muted:#6b7684; --line:#e4e8ed; --accent:#2f6df0; --accent-soft:#eaf0fe; }
9	  * { box-sizing:border-box; }
10	  body { margin:0; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif; background:var(--bg); color:var(--ink); }
11	  header { background:var(--card); border-bottom:1px solid var(--line); padding:16px 24px; }
12	  header h1 { margin:0; font-size:18px; }
13	  header p { margin:4px 0 0; color:var(--muted); font-size:13px; }
14	  main { max-width:760px; margin:0 auto; padding:24px 16px 64px; }
15	  .panel { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:18px; margin-bottom:24px; }
16	  .panel h2 { margin:0 0 14px; font-size:14px; text-transform:uppercase; letter-spacing:.04em; color:var(--muted); }
17	  label { display:block; font-size:12px; color:var(--muted); margin:12px 0 4px; }
18	  input[type=text], input[type=url], textarea { width:100%; padding:10px 12px; border:1px solid var(--line); border-radius:8px; font-size:14px; font-family:inherit; background:#fff; }
19	  textarea { resize:vertical; min-height:60px; }
20	  .row-url { display:flex; gap:8px; }
21	  .row-url input { flex:1; }
22	  button { cursor:pointer; border:none; border-radius:8px; font-size:14px; padding:10px 16px; font-weight:600; }
23	  .btn-primary { background:var(--accent); color:#fff; }
24	  .btn-primary:disabled { opacity:.45; cursor:not-allowed; }
25	  .btn-ghost { background:var(--accent-soft); color:var(--accent); }
26	  .fetch-note { font-size:12px; color:var(--muted); margin-top:6px; min-height:16px; }
27	  .fetch-note.filled { color:#1a8a4a; }
28	  .save-row { margin-top:18px; display:flex; justify-content:flex-end; }
29	  .list-head { display:flex; align-items:baseline; justify-content:space-between; margin-bottom:8px; }
30	  .count { color:var(--muted); font-size:13px; }
31	  .empty { text-align:center; color:var(--muted); padding:40px 12px; }
32	  .empty svg { opacity:.4; }
33	  ul.bm { list-style:none; margin:0; padding:0; }
34	
35	  /* favicon chip */
36	  .favicon { width:18px; height:18px; border-radius:4px; display:inline-flex; align-items:center; justify-content:center; color:#fff; font-size:11px; font-weight:700; flex:0 0 auto; }
37	  .site-row { display:flex; align-items:center; gap:6px; }
38	
39	  /* auto-collected preview block in form */
40	  .auto { margin-top:14px; border:1px dashed var(--line); border-radius:10px; padding:12px; background:#fbfcfe; display:none; }
41	  .auto .auto-label { font-size:11px; text-transform:uppercase; letter-spacing:.04em; color:var(--muted); margin-bottom:8px; }
42	  .auto .auto-body { display:flex; gap:12px; align-items:center; }
43	  .auto .preview { width:120px; height:68px; border-radius:8px; object-fit:cover; border:1px solid var(--line); flex:0 0 auto; background:#eef1f5; }
44	  .auto .preview-none { width:120px; height:68px; border-radius:8px; border:1px dashed var(--line); display:flex; align-items:center; justify-content:center; color:var(--muted); font-size:11px; text-align:center; flex:0 0 auto; padding:4px; }
45	
46	  li.bm-item { border:1px solid var(--line); border-radius:10px; padding:14px 16px; margin-bottom:10px; background:#fff; display:flex; gap:14px; }
47	  li.bm-item .thumb { width:96px; height:64px; border-radius:8px; object-fit:cover; border:1px solid var(--line); flex:0 0 auto; }
48	  li.bm-item .thumb-none { width:96px; height:64px; border-radius:8px; border:1px dashed var(--line); flex:0 0 auto; display:flex; align-items:center; justify-content:center; color:var(--muted); font-size:10px; text-align:center; padding:3px; }
49	  li.bm-item .body { flex:1; min-width:0; }
50	  li.bm-item .title { font-size:15px; font-weight:600; margin:0 0 3px; }
51	  li.bm-item .title a { color:var(--ink); text-decoration:none; }
52	  li.bm-item .site { font-size:12px; color:var(--muted); }
53	  li.bm-item .desc { font-size:13px; color:#48525f; margin:8px 0 0; }
54	  li.bm-item .tags { margin-top:10px; display:flex; flex-wrap:wrap; gap:6px; }
55	  .tag { background:var(--accent-soft); color:var(--accent); font-size:12px; padding:3px 9px; border-radius:20px; }
56	  li.bm-item .note { margin-top:8px; font-size:13px; color:#48525f; border-left:3px solid var(--line); padding-left:10px; }
57	  .flash { background:#e8f7ee; color:#1a8a4a; border:1px solid #bfe6cd; border-radius:8px; padding:10px 12px; font-size:13px; margin-bottom:16px; display:none; }
58	</style>
59	</head>
60	<body>
61	<header>
62	  <h1>My Bookmarks</h1>
63	  <p>A private place for your links — prototype for review</p>
64	</header>
65	<main>
66	  <div id="flash" class="flash"></div>
67	
68	  <section class="panel">
69	    <h2>Save a link</h2>
70	    <label for="url">Web address</label>
71	    <div class="row-url">
72	      <input id="url" type="url" placeholder="Paste a web address, e.g. https://example.com/article" autocomplete="off" />
73	      <button id="fetchBtn" class="btn-ghost" type="button">Get details</button>
74	    </div>
75	    <div id="fetchNote" class="fetch-note"></div>
76	
77	    <div id="auto" class="auto">
78	      <div class="auto-label">Collected automatically</div>
79	      <div class="auto-body">
80	        <div id="autoPreview"></div>
81	        <div class="site-row"><span id="autoFavicon"></span><span id="autoSite" class="site"></span></div>
82	      </div>
83	    </div>
84	
85	    <label for="title">Title</label>
86	    <input id="title" type="text" placeholder="The page title will appear here — edit if you like" />
87	
88	    <label for="desc">Description</label>
89	    <textarea id="desc" placeholder="A short summary of the page"></textarea>
90	
91	    <label for="tags">Tags (comma separated)</label>
92	    <input id="tags" type="text" placeholder="e.g. design, reading, work" />
93	
94	    <label for="note">Your note</label>
95	    <textarea id="note" placeholder="Why you saved this, or anything to remember"></textarea>
96	
97	    <div class="save-row">
98	      <button id="saveBtn" class="btn-primary" type="button" disabled>Save bookmark</button>
99	    </div>
100	  </section>
101	
102	  <section class="panel">
103	    <div class="list-head">
104	      <h2 style="margin:0">Your bookmarks</h2>
105	      <span id="count" class="count"></span>
106	    </div>
107	    <div id="empty" class="empty">
108	      <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M6 4h12a1 1 0 0 1 1 1v15l-7-4-7 4V5a1 1 0 0 1 1-1z"/></svg>
109	      <p>No bookmarks yet.<br/>Paste a web address above to save your first one.</p>
110	    </div>
111	    <ul id="list" class="bm"></ul>
112	  </section>
113	</main>
114	
115	<script>
116	// --- Simulated page-detail lookup (prototype only) ---
117	// Stands in for the real "fetch the page's details" behaviour so we can explore
118	// the flow without a live server. Returns plausible details from the address,
119	// including a site icon and (when available) a preview image.
120	function banner(text, c1, c2){
121	  const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="240" height="135">'+
122	    '<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1">'+
123	    '<stop offset="0" stop-color="'+c1+'"/><stop offset="1" stop-color="'+c2+'"/></linearGradient></defs>'+
124	    '<rect width="240" height="135" fill="url(#g)"/>'+
125	    '<text x="16" y="120" font-family="Arial" font-size="16" fill="#ffffff" opacity="0.9">'+text+'</text></svg>';
126	  return 'data:image/svg+xml;utf8,'+encodeURIComponent(svg);
127	}
128	const CANNED = {
129	  "nytimes.com":   { title:"The Science of a Good Night's Sleep", desc:"How small evening habits change how rested you feel.", site:"The New York Times", preview:banner("nytimes.com","#111827","#374151") },
130	  "github.com":    { title:"tldr-pages/tldr: Simplified man pages", desc:"Community-maintained help pages for command-line tools.", site:"GitHub", preview:banner("github.com","#24292f","#57606a") },
131	  "wikipedia.org": { title:"Bookmark (digital) — Wikipedia", desc:"A saved shortcut used to return to a web page later.", site:"Wikipedia", preview:banner("wikipedia.org","#3366cc","#6699ff") },
132	  "medium.com":    { title:"Designing Calm Software", desc:"An essay on interfaces that respect your attention.", site:"Medium", preview:banner("medium.com","#0f9d58","#34c77b") }
133	};
134	function domainOf(url){
135	  try { return new URL(url).hostname.replace(/^www\./,""); } catch(e){ return ""; }
136	}
137	function faviconColor(host){
138	  let h=0; for (let i=0;i<host.length;i++){ h=(h*31+host.charCodeAt(i))>>>0; }
139	  const hue = h % 360; return "hsl("+hue+",55%,45%)";
140	}
141	function faviconHtml(host, size){
142	  const letter = (host||"?").charAt(0).toUpperCase();
143	  const s = size||18;
144	  return '<span class="favicon" style="background:'+faviconColor(host)+';width:'+s+'px;height:'+s+'px;font-size:'+Math.round(s*0.6)+'px">'+letter+'</span>';
145	}
146	function lookup(url){
147	  const host = domainOf(url);
148	  for (const key in CANNED){ if (host.endsWith(key)) return { ...CANNED[key] }; }
149	  const path = (function(){ try { return new URL(url).pathname; } catch(e){ return ""; } })();
150	  const slug = path.split("/").filter(Boolean).pop() || host;
151	  const pretty = slug.replace(/[-_]+/g," ").replace(/\.\w+$/,"").replace(/\b\w/g, c=>c.toUpperCase());
152	  // generic pages: site icon is available, but no preview image
153	  return { title: pretty || host, desc:"", site: host, preview: null };
154	}
155	
156	const bookmarks = [];
157	const $ = id => document.getElementById(id);
158	let current = null; // holds auto-collected site/preview for the pending save
159	
160	function refreshSaveState(){
161	  const hasUrl = $("url").value.trim() !== "";
162	  const hasTitle = $("title").value.trim() !== "";
163	  $("saveBtn").disabled = !(hasUrl && hasTitle);
164	}
165	
166	$("fetchBtn").addEventListener("click", () => {
167	  const url = $("url").value.trim();
168	  const note = $("fetchNote");
169	  if (!url){ note.textContent = "Paste a web address first."; note.className="fetch-note"; return; }
170	  const d = lookup(url);
171	  const host = domainOf(url);
172	  $("title").value = d.title;
173	  $("desc").value = d.desc;
174	  current = { site: d.site || host, host: host, preview: d.preview };
175	  // show auto-collected block
176	  $("auto").style.display = "block";
177	  $("autoFavicon").innerHTML = faviconHtml(host, 18);
178	  $("autoSite").textContent = d.site || host;
179	  $("autoPreview").innerHTML = d.preview
180	    ? '<img class="preview" src="'+d.preview+'" alt="preview" />'
181	    : '<div class="preview-none">No preview image on this page</div>';
182	  note.textContent = "Details filled in automatically — edit the title, description, tags or note as you like.";
183	  note.className = "fetch-note filled";
184	  refreshSaveState();
185	});
186	
187	["url","title"].forEach(id => $(id).addEventListener("input", refreshSaveState));
188	
189	$("saveBtn").addEventListener("click", () => {
190	  const host = domainOf($("url").value.trim());
191	  const bm = {
192	    url: $("url").value.trim(),
193	    title: $("title").value.trim(),
194	    desc: $("desc").value.trim(),
195	    tags: $("tags").value.split(",").map(t=>t.trim()).filter(Boolean),
196	    note: $("note").value.trim(),
197	    site: (current && current.site) || host,
198	    host: host,
199	    preview: current ? current.preview : null
200	  };
201	  bookmarks.unshift(bm);
202	  render();
203	  ["url","title","desc","tags","note"].forEach(id => $(id).value="");
204	  $("fetchNote").textContent=""; $("fetchNote").className="fetch-note";
205	  $("auto").style.display="none"; current=null;
206	  refreshSaveState();
207	  const f = $("flash"); f.textContent = "Saved. It's now in your list below."; f.style.display="block";
208	  setTimeout(()=>{ f.style.display="none"; }, 3000);
209	});
210	
211	function render(){
212	  const list = $("list"); list.innerHTML="";
213	  $("count").textContent = bookmarks.length ? bookmarks.length + (bookmarks.length===1?" link":" links") : "";
214	  $("empty").style.display = bookmarks.length ? "none" : "block";
215	  bookmarks.forEach(bm => {
216	    const li = document.createElement("li"); li.className="bm-item";
217	    const thumb = bm.preview
218	      ? '<img class="thumb" src="'+bm.preview+'" alt="preview" />'
219	      : '<div class="thumb-none">No preview</div>';
220	    li.innerHTML =
221	      thumb +
222	      '<div class="body">'+
223	        '<p class="title"><a href="'+bm.url+'" target="_blank" rel="noopener">'+escapeHtml(bm.title)+'</a></p>'+
224	        '<div class="site-row">'+faviconHtml(bm.host,16)+'<span class="site">'+escapeHtml(bm.site)+'</span></div>'+
225	        (bm.desc ? '<p class="desc">'+escapeHtml(bm.desc)+'</p>' : '')+
226	        (bm.tags.length ? '<div class="tags">'+bm.tags.map(t=>'<span class="tag">'+escapeHtml(t)+'</span>').join('')+'</div>' : '')+
227	        (bm.note ? '<div class="note">'+escapeHtml(bm.note)+'</div>' : '')+
228	      '</div>';
229	    list.appendChild(li);
230	  });
231	}
232	function escapeHtml(s){ return (s||"").replace(/[&<>"']/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])); }
233	
234	render();
235	document.body.setAttribute("data-harness-ready","true");
236	</script>
237	</body>
238	</html>
