  $("saveBtn").addEventListener("click", () => {
    const host = domainOf($("url").value.trim());
    bookmarks.unshift({
      url:$("url").value.trim(), title:$("title").value.trim(), desc:$("desc").value.trim(),
      tags:$("tags").value.split(",").map(t=>t.trim()).filter(Boolean), note:$("note").value.trim(),
