function matchesTag(bm){
  if (!activeTag) return true;
  return bm.tags.map(t=>t.toLowerCase()).indexOf(activeTag.toLowerCase()) >= 0;
}
function hl(text){
  if (!query) return escapeHtml(text);
  const t=text||"", lc=t.toLowerCase(), q=query; let out="", i=0;
