.filterbar { display:flex; flex-wrap:wrap; gap:6px; margin-bottom:12px; align-items:center; }
.filterbar .flabel { font-size:12px; color:var(--muted); margin-right:2px; }
.fchip { background:#eef1f5; color:#48525f; font-size:12px; padding:5px 11px; border-radius:20px; cursor:pointer; border:1px solid transparent; }
