.viewtabs button.active { color:var(--accent); border-bottom-color:var(--accent); }
.viewtabs .tabn { background:#eef1f5; color:var(--muted); font-size:11px; padding:1px 7px; border-radius:20px; margin-left:4px; }
.viewtabs button.active .tabn { background:var(--accent-soft); color:var(--accent); }
/* card actions */
.cardactions { margin-top:12px; display:flex; gap:8px; flex-wrap:wrap; }
.linkbtn { background:transparent; color:var(--accent); border:1px solid var(--line); border-radius:8px; padding:5px 10px; font-size:12px; font-weight:600; }
.linkbtn:hover { background:var(--accent-soft); }
.linkbtn.on { background:var(--accent-soft); border-color:var(--accent-soft); }
