const saveEdit=e.target.closest('[data-act="edit-save"]');
if (saveEdit){ const bm=findById(parseInt(saveEdit.getAttribute("data-id"),10));
  if(bm){ const li=saveEdit.closest("li");
    const err=li.querySelector(".ed-error");
    // Validate the (editable) web address.
    let newUrl = li.querySelector(".ed-url").value.trim();
    if (!newUrl){ err.textContent="A web address is required."; return; }
    if (!/^[a-z][a-z0-9+.-]*:\/\//i.test(newUrl)) newUrl="https://"+newUrl;
    let newHost="";
    try { const u=new URL(newUrl); newHost=u.hostname.replace(/^www\./,""); if(!newHost||newHost.indexOf(".")<0) throw new Error(); }
    catch(_){ err.textContent="That doesn't look like a web address."; return; }
    // Prevent changing to an address that another bookmark already uses.
    const clash = bookmarks.find(b => b.id!==bm.id && b.url.trim().toLowerCase()===newUrl.toLowerCase());
    if (clash){ err.textContent="Another bookmark already uses that address"+(clash.archived?" (in Archived)":clash.readLater?" (in Read later)":"")+"."; return; }
    bm.url = newUrl; bm.host = newHost; bm.site = (lookup(newUrl).site) || newHost;
    const t=li.querySelector(".ed-title").value.trim();
    bm.title = t || bm.title;
    bm.desc = li.querySelector(".ed-desc").value.trim();
    bm.tags = li.querySelector(".ed-tags").value.split(",").map(x=>x.trim()).filter(Boolean);
    bm.note = li.querySelector(".ed-note").value.trim();
  }
  editingId=null; render();
  const f=$("flash"); f.textContent="Changes saved."; f.style.display="block"; setTimeout(()=>f.style.display="none",3000);
  return; }

