:root {
  --bg:#f6f7f9; --card:#fff; --ink:#1c2430; --muted:#6b7684;
  --line:#e4e8ed; --accent:#2f6df0; --accent-soft:#eaf0fe;
  --danger:#b23b3b; --ok:#1a8a4a;
}
* { box-sizing:border-box; }
body { margin:0; font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif; background:var(--bg); color:var(--ink); }
header { background:var(--card); border-bottom:1px solid var(--line); padding:16px 24px; }
header h1 { margin:0; font-size:18px; }
header p { margin:4px 0 0; color:var(--muted); font-size:13px; }
main { max-width:760px; margin:0 auto; padding:24px 16px 64px; }
.panel { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:18px; margin-bottom:24px; }
.panel h2 { margin:0 0 14px; font-size:14px; text-transform:uppercase; letter-spacing:.04em; color:var(--muted); }
label { display:block; font-size:12px; color:var(--muted); margin:12px 0 4px; }
input[type=text], input[type=url], input[type=search], textarea, select {
  width:100%; padding:10px 12px; border:1px solid var(--line); border-radius:8px;
  font-size:14px; font-family:inherit; background:#fff; color:inherit;
}
select { cursor:pointer; }
textarea { resize:vertical; min-height:60px; }
.row-url { display:flex; gap:8px; }
.row-url input { flex:1; }
button { cursor:pointer; border:none; border-radius:8px; font-size:14px; padding:10px 16px; font-weight:600; }
.btn-primary { background:var(--accent); color:#fff; }
.btn-primary:disabled { opacity:.45; cursor:not-allowed; }
.btn-ghost { background:var(--accent-soft); color:var(--accent); }
.fetch-note { font-size:12px; color:var(--muted); margin-top:6px; min-height:16px; }
.fetch-note.filled { color:var(--ok); }
.fetch-note.error { color:var(--danger); }
.save-row { margin-top:18px; display:flex; justify-content:flex-end; }
.list-head { display:flex; align-items:baseline; justify-content:space-between; margin-bottom:12px; gap:12px; }
.count { color:var(--muted); font-size:13px; white-space:nowrap; }
.empty { text-align:center; color:var(--muted); padding:40px 12px; }
ul.bm { list-style:none; margin:0; padding:0; }

.favicon { width:18px; height:18px; border-radius:4px; display:inline-flex; align-items:center; justify-content:center; color:#fff; font-size:11px; font-weight:700; flex:0 0 auto; }
.favicon-img { width:18px; height:18px; border-radius:4px; object-fit:cover; flex:0 0 auto; background:#eef1f5; }
.site-row { display:flex; align-items:center; gap:6px; }

.auto { margin-top:14px; border:1px dashed var(--line); border-radius:10px; padding:12px; background:#fbfcfe; }
.auto .auto-label { font-size:11px; text-transform:uppercase; letter-spacing:.04em; color:var(--muted); margin-bottom:8px; }
.auto .auto-body { display:flex; gap:12px; align-items:center; }
.auto .preview { width:120px; height:68px; border-radius:8px; object-fit:cover; border:1px solid var(--line); flex:0 0 auto; background:#eef1f5; }
.auto .preview-none { width:120px; height:68px; border-radius:8px; border:1px dashed var(--line); display:flex; align-items:center; justify-content:center; color:var(--muted); font-size:11px; text-align:center; flex:0 0 auto; padding:4px; }

li.bm-item { border:1px solid var(--line); border-radius:10px; padding:14px 16px; margin-bottom:10px; background:#fff; display:flex; gap:14px; }
li.bm-item .thumb { width:96px; height:64px; border-radius:8px; object-fit:cover; border:1px solid var(--line); flex:0 0 auto; background:#eef1f5; }
li.bm-item .thumb-none { width:96px; height:64px; border-radius:8px; border:1px dashed var(--line); flex:0 0 auto; display:flex; align-items:center; justify-content:center; color:var(--muted); font-size:10px; text-align:center; padding:3px; }
li.bm-item .body { flex:1; min-width:0; }
li.bm-item .title { font-size:15px; font-weight:600; margin:0 0 3px; }
li.bm-item .title a { color:var(--ink); text-decoration:none; }
li.bm-item .title a:hover { text-decoration:underline; }
li.bm-item .site { font-size:12px; color:var(--muted); }
li.bm-item .desc { font-size:13px; color:#48525f; margin:8px 0 0; }
li.bm-item .tags { margin-top:10px; display:flex; flex-wrap:wrap; gap:6px; }
.tag { background:var(--accent-soft); color:var(--accent); font-size:12px; padding:3px 9px; border-radius:20px; }
.tag.clickable { cursor:pointer; }
.tag.clickable:hover { background:#d8e4fd; }
li.bm-item .note { margin-top:8px; font-size:13px; color:#48525f; border-left:3px solid var(--line); padding-left:10px; }
li.bm-item .title, li.bm-item .desc, li.bm-item .note, li.bm-item .site, .editform .site { overflow-wrap:anywhere; word-break:break-word; }
mark { background:#fff2a8; color:inherit; border-radius:3px; padding:0 1px; }

.flash { background:#e8f7ee; color:var(--ok); border:1px solid #bfe6cd; border-radius:8px; padding:10px 12px; font-size:13px; margin-bottom:16px; }
.flash[hidden] { display:none; }

.searchwrap { position:relative; margin-bottom:6px; }
.searchwrap input { padding-left:34px; }
.searchwrap svg { position:absolute; left:11px; top:50%; transform:translateY(-50%); color:var(--muted); }

.tagwrap { position:relative; }
.tagsuggest { position:absolute; left:0; right:0; top:calc(100% + 4px); background:#fff; border:1px solid var(--line); border-radius:8px; box-shadow:0 6px 20px rgba(0,0,0,.08); z-index:20; overflow:hidden; }
.tagsuggest[hidden] { display:none; }
.tagsuggest .opt { padding:9px 12px; font-size:14px; cursor:pointer; display:flex; align-items:center; gap:8px; }
.tagsuggest .opt:hover, .tagsuggest .opt.active { background:var(--accent-soft); }
.tagsuggest .opt .dot { width:8px; height:8px; border-radius:50%; background:var(--accent); }
.tagsuggest .opt small { color:var(--muted); margin-left:auto; }

.viewtabs { display:flex; gap:6px; margin-bottom:14px; border-bottom:1px solid var(--line); }
.viewtabs button { background:transparent; color:var(--muted); border:none; border-bottom:2px solid transparent; border-radius:0; padding:8px 12px; font-weight:600; font-size:14px; margin-bottom:-1px; }
.viewtabs button.active { color:var(--accent); border-bottom-color:var(--accent); }
.viewtabs .tabn { background:#eef1f5; color:var(--muted); font-size:11px; padding:1px 7px; border-radius:20px; margin-left:4px; }
.viewtabs button.active .tabn { background:var(--accent-soft); color:var(--accent); }

.activefilter { display:flex; align-items:center; gap:8px; background:var(--accent-soft); color:var(--accent); font-size:13px; padding:8px 12px; border-radius:8px; margin-bottom:12px; }
.activefilter[hidden] { display:none; }
.activefilter button { background:transparent; color:var(--accent); padding:2px 6px; font-size:14px; }

.sortrow { display:flex; align-items:center; gap:8px; margin-bottom:12px; }
.sortrow label { margin:0; font-size:12px; color:var(--muted); white-space:nowrap; }
