async function onSave() {
  const url = $("url").value.trim();
  const meta = state.pendingMeta || {};
  const payload = {
    url,
    title: $("title").value.trim(),
    description: $("desc").value.trim(),
    tags: $("tags").value,
    note: $("note").value.trim(),
    site: meta.site,
    image: meta.image || null,
    icon: meta.icon || null,
  };
